from pathlib import Path
from docx import Document
from docx.shared import Inches, Pt, RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.enum.table import WD_CELL_VERTICAL_ALIGNMENT
from docx.oxml import OxmlElement
from docx.oxml.ns import qn

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'manuales'/'version_ampliada'
PICS=ROOT/'tmp'/'manuales-capturas'
OUT.mkdir(parents=True,exist_ok=True)

def field(par, instruction):
    run=par.add_run(); begin=OxmlElement('w:fldChar');begin.set(qn('w:fldCharType'),'begin');instr=OxmlElement('w:instrText');instr.set(qn('xml:space'),'preserve');instr.text=instruction; separate=OxmlElement('w:fldChar');separate.set(qn('w:fldCharType'),'separate');text=OxmlElement('w:t');text.text='Actualice el índice en Word si es necesario.';end=OxmlElement('w:fldChar');end.set(qn('w:fldCharType'),'end')
    for element in (begin,instr,separate,text,end):run._r.append(element)

def add_page(d):d.add_page_break()
def heading(d,t,l=1):d.add_heading(t,level=l)
def para(d,t):
    p=d.add_paragraph(t);p.paragraph_format.space_after=Pt(6);return p
def steps(d,seq):
    for n,s in enumerate(seq,1):
        p=d.add_paragraph(f'{n}. {s}');p.paragraph_format.left_indent=Inches(.2);p.paragraph_format.space_after=Pt(5)
def bullets(d,seq):
    for s in seq:d.add_paragraph(s,style='List Bullet')
def table(d,heads,rows):
    t=d.add_table(rows=1,cols=len(heads));t.style='Table Grid';t.autofit=True
    for i,x in enumerate(heads):
        cell=t.rows[0].cells[i];cell.text=x
        for r in cell.paragraphs[0].runs:r.bold=True;r.font.color.rgb=RGBColor(255,255,255)
        sh=OxmlElement('w:shd');sh.set(qn('w:fill'),'17365D');cell._tc.get_or_add_tcPr().append(sh)
    for row in rows:
        cells=t.add_row().cells
        for i,x in enumerate(row):cells[i].text=str(x);cells[i].vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
    for row in t.rows:
        for cell in row.cells:
            for p in cell.paragraphs:
                p.paragraph_format.space_after=Pt(3)
                for r in p.runs:r.font.size=Pt(9)
    d.add_paragraph()
def image(d,name,caption,explain):
    f=PICS/(name+'.png')
    if not f.exists():return
    p=d.add_paragraph();p.alignment=WD_ALIGN_PARAGRAPH.CENTER;p.paragraph_format.keep_with_next=True;p.add_run().add_picture(str(f),width=Inches(5.5))
    p=d.add_paragraph('Figura. '+caption);p.alignment=WD_ALIGN_PARAGRAPH.CENTER;p.paragraph_format.keep_with_next=True
    for r in p.runs:r.italic=True;r.font.size=Pt(9)
    para(d,explain)
def newdoc(title,subtitle):
    d=Document();sec=d.sections[0];sec.top_margin=Inches(.75);sec.bottom_margin=Inches(.7);sec.left_margin=Inches(.85);sec.right_margin=Inches(.85)
    styles=d.styles;styles['Normal'].font.name='Calibri';styles['Normal'].font.size=Pt(10.5)
    styles['Normal'].paragraph_format.line_spacing=1.12
    for n in ['Title','Heading 1','Heading 2','Heading 3']:
        styles[n].font.name='Calibri';styles[n].font.color.rgb=RGBColor(0,0,0)
    styles['Title'].font.size=Pt(25)
    p=d.add_paragraph();p.alignment=WD_ALIGN_PARAGRAPH.CENTER;p.add_run('CONSULTORÍA FINANCIERA JME GUATEMALA').bold=True
    d.add_paragraph('\n\n');p=d.add_paragraph(style='Title');p.alignment=WD_ALIGN_PARAGRAPH.CENTER;p.add_run(title)
    p=d.add_paragraph(subtitle);p.alignment=WD_ALIGN_PARAGRAPH.CENTER
    p=d.add_paragraph('Sistema de gestión de créditos en mora y cobranza');p.alignment=WD_ALIGN_PARAGRAPH.CENTER
    p=d.add_paragraph('Versión 2.0   |   Noviembre de 2026');p.alignment=WD_ALIGN_PARAGRAPH.CENTER
    add_page(d);heading(d,'Control del documento');table(d,['Elemento','Descripción'],[('Sistema','Gestión de créditos en mora y cobranza JME'),('Documento',title),('Versión','2.0'),('Fecha','Noviembre de 2026'),('Estado','Documento de consulta y capacitación'),('Uso','Interno')])
    para(d,'Las capturas incluidas muestran la aplicación en ejecución con datos de demostración. Las opciones y los resultados visibles dependen del usuario, sus permisos y los datos registrados.')
    heading(d,'Contenido');field(d.add_paragraph(),' TOC \\o "1-2" \\h \\z \\u ');add_page(d)
    footer=sec.footer.paragraphs[0];footer.alignment=WD_ALIGN_PARAGRAPH.RIGHT;footer.add_run('JME | Página ');field(footer,' PAGE ')
    settings=d.settings.element; update=OxmlElement('w:updateFields');update.set(qn('w:val'),'true');settings.append(update)
    return d

def user_manual():
    d=newdoc('Manual de usuario','Procedimientos operativos detallados')
    heading(d,'1 Información general');heading(d,'1.1 Objetivo y destinatarios',2)
    para(d,'Orientar a administradores, supervisores, gestores y personal de consulta en las actividades de seguimiento y recuperación de cartera. Cada procedimiento indica qué se necesita, qué hacer y cómo comprobar el resultado.')
    heading(d,'1.2 Alcance y convenciones',2);para(d,'El sistema centraliza clientes, créditos, convenios, pagos, gestiones, usuarios, reportes y alertas. Los nombres de botones se escriben en negrita conceptual y deben buscarse en la pantalla indicada. Los importes se presentan en quetzales (Q). Algunas opciones pueden no aparecer según los permisos concedidos.')
    heading(d,'2 Acceso y entorno de trabajo');heading(d,'2.1 Requisitos previos',2);bullets(d,['Contar con una cuenta activa, correo y contraseña.','Disponer de la dirección de acceso, navegador actualizado y conexión al servidor.','Tener permiso de lectura o de creación/edición para la tarea que se va a realizar.'])
    heading(d,'2.2 Inicio y cierre de sesión',2);image(d,'login','Pantalla de acceso','Escriba el correo y la contraseña de su cuenta activa para ingresar al sistema.');steps(d,['Abra la dirección indicada por soporte; en una instalación local puede ser http://localhost:3000.','Escriba su correo y contraseña y pulse Acceder al Sistema.','Espere la carga del panel y verifique el nombre y rol en la parte superior.','Para terminar, pulse Cerrar sesión y espere el regreso a la pantalla de acceso.'])
    para(d,'Comprobación: se muestra el menú correspondiente a los permisos. La sesión tiene una duración máxima de ocho horas; al vencer debe autenticarse otra vez. Si las credenciales son rechazadas, verifique el correo y solicite apoyo al administrador.')
    heading(d,'2.3 Panel principal y navegación',2);image(d,'dashboard','Panel de control general','El panel reúne indicadores, alertas y accesos directos. El menú lateral permite abrir cada módulo; en pantallas pequeñas se accede con el botón de menú.')
    para(d,'Revise cartera vencida, clientes en mora, monto recuperado y porcentaje de recuperación. Pulse Ver Reporte Completo para ampliar la consulta. Algunos textos informativos del prototipo pueden mostrar cifras fijas; confirme los indicadores en el reporte y en los registros antes de tomar decisiones.')
    heading(d,'3 Gestión de clientes');heading(d,'3.1 Consulta y filtros',2);image(d,'clientes','Listado de clientes','La pantalla presenta tarjetas, búsqueda, filtros y tabla. La fila contiene código, cliente, teléfono, saldo, días de mora y estado.')
    steps(d,['Abra Gestión de clientes.','Busque por nombre, código o teléfono; si lo requiere, seleccione estado, rango de mora o gestor.','Abra el detalle desde la fila o el icono de visualización.','Revise identificación, contacto, saldo, estado, notas y gestiones existentes.'])
    para(d,'Comprobación: el registro consultado coincide con el cliente y su saldo. Exportar descarga un archivo CSV con la selección visible.')
    heading(d,'3.2 Crear cliente',2);image(d,'nuevo-cliente','Formulario de nuevo cliente','El formulario reúne identificación, contacto, saldo inicial, días de mora, segmento, estado y gestor asignado.')
    steps(d,['Pulse Nuevo cliente.','Ingrese nombre completo, NIT, teléfono y, si aplica, correo y dirección.','Registre saldo pendiente en Q y días de mora como número entero.','Seleccione segmento, estado inicial y gestor asignado.','Revise los datos y pulse el botón para guardar.'])
    para(d,'Comprobación: el nuevo cliente aparece en el listado y su expediente muestra el saldo indicado. El NIT se valida como único; use un identificador individual y verifique antes de registrar. El saldo inicial crea la cuenta de crédito consolidada del cliente.')
    heading(d,'3.3 Historial y acciones',2);para(d,'Desde el detalle puede consultar el historial y abrir el formulario para registrar una gestión. Antes de contactar al cliente, revise la última acción y su resultado. Los puntajes se calculan por reglas de mora y saldo y son orientativos; no son una probabilidad estadística validada.')
    heading(d,'4 Registro de pagos');heading(d,'4.1 Registrar un abono',2);image(d,'pagos','Registro de pagos','El formulario solicita cliente, convenio opcional, importe y referencia bancaria; a la derecha se presenta el historial de abonos.')
    steps(d,['Abra Registro de pagos y seleccione el cliente.','Verifique el saldo pendiente mostrado.','Seleccione el convenio cuando corresponda.','Ingrese el monto positivo con hasta dos decimales y una referencia bancaria única.','Pulse Registrar pago y espere el mensaje de confirmación.','Verifique el abono en el listado y el saldo actualizado en el expediente o convenio.'])
    para(d,'El sistema rechaza referencias duplicadas y pagos superiores al saldo del crédito o convenio. Si existe un convenio activo y no selecciona uno, el servidor lo aplica automáticamente. Si se interrumpe la respuesta, consulte el listado antes de intentar otra vez para evitar duplicaciones.')
    heading(d,'4.2 Resultado del pago',2);para(d,'El pago se aplica a las cuotas en orden y admite abonos parciales. Al completar una cuota cambia a Pagado. Si se cubre todo el saldo del convenio, este pasa a Liquidado. Un descuento pactado no condona automáticamente la diferencia del crédito.')
    heading(d,'5 Convenios de pago');heading(d,'5.1 Consultar convenios',2);image(d,'convenios','Listado de convenios','La tabla permite consultar código, cliente, saldo inicial, monto convenido, cuotas, próximo pago y estado. El buscador y los filtros ayudan a ubicar un caso.')
    heading(d,'5.2 Crear un convenio',2);image(d,'nuevo-convenio','Formulario de convenio','Se selecciona un cliente con saldo y se registran las condiciones del acuerdo.')
    steps(d,['Pulse Nuevo convenio y seleccione el cliente.','Confirme los datos y saldo del expediente.','Ingrese monto pactado, número de cuotas, frecuencia semanal, quincenal o mensual, fecha de inicio, gestor y observaciones.','Compruebe que el monto pactado sea positivo y no supere el saldo.','Pulse Crear convenio formal y revise el calendario generado.'])
    para(d,'Comprobación: el cliente pasa a Convenio vigente y el convenio aparece en la lista. No se puede crear otro acuerdo activo para el mismo cliente. El residuo de centavos se incorpora a la última cuota.')
    heading(d,'6 Seguimiento de gestiones');heading(d,'6.1 Registrar una gestión',2);image(d,'gestores','Seguimiento de gestores','La pantalla permite consultar gestiones por cliente, gestor, canal y resultado, además de registrar una nueva actividad.')
    steps(d,['Abra Seguimiento de gestores de cobro y pulse Nueva gestión; también puede iniciar una gestión desde el expediente.','Seleccione el cliente y el canal: llamada, WhatsApp, visita o correo.','Seleccione el resultado e ingrese notas claras del contacto.','Si corresponde, registre monto prometido, fecha y objetivo de la próxima acción.','Guarde y compruebe la actividad en el listado y el historial del cliente.'])
    para(d,'La autoría se toma de la sesión autenticada. Registrar una gestión no envía un mensaje ni acredita un pago. Una promesa de pago debe verificarse cuando llegue la fecha acordada.')
    heading(d,'7 Alertas y reportes');heading(d,'7.1 Evaluar y atender alertas',2)
    steps(d,['En el panel principal pulse Evaluar alertas o abra el panel desde la campana.','Revise cliente, saldo, días de mora, severidad, descripción y acción sugerida.','Si la acción requiere seguimiento, regístrela según el procedimiento interno.','Use la opción de poner en proceso o resolver cuando corresponda y verifique el nuevo estado.'])
    para(d,'La evaluación inicial aplica reglas sobre saldo y días de mora. La bandeja de acciones queda pendiente de integración con un proveedor: no existe confirmación de envío real de WhatsApp o correo. El horario y canal son sugerencias generales.')
    heading(d,'7.2 Consultar y exportar reportes',2);image(d,'reportes','Reporte de cartera','El reporte muestra indicadores, rangos de mora, recuperación por mes y resumen por segmento.')
    steps(d,['Abra Reportes de cartera vencida.','Aplique filtros de estado y días de mora.','Ingrese fechas desde y hasta para limitar los pagos considerados.','Revise saldo actual y recuperaciones del período.','Pulse Exportar CSV o Imprimir / PDF según el resultado deseado.'])
    para(d,'Las fechas filtran pagos, mientras el saldo representa el estado actual. La recuperación se calcula como pagos del período divididos entre saldo actual más dichos pagos. CSV se puede abrir en una hoja de cálculo; Imprimir / PDF usa el diálogo del navegador.')
    heading(d,'8 Usuarios y permisos');heading(d,'8.1 Crear y administrar cuentas',2);image(d,'usuarios','Usuarios y permisos','El administrador consulta usuarios, roles y estados, y accede a la matriz de permisos.')
    steps(d,['Entre a Usuarios y permisos con una cuenta administradora.','Pulse Nuevo usuario e ingrese nombre, usuario, correo, rol y contraseña inicial de al menos 12 caracteres.','Defina permisos de visualización, creación y edición por módulo.','Guarde y compruebe la cuenta en el listado.','Para modificar permisos, use el icono correspondiente; para activar o desactivar, pulse el estado.'])
    para(d,'Solo el administrador puede crear cuentas o cambiar sus permisos y estado. Al desactivar una cuenta se revocan sus sesiones. La cuenta actual no puede desactivarse a sí misma. No se exponen eliminaciones de registros financieros.')
    heading(d,'9 Problemas frecuentes y apoyo');table(d,['Situación','Comprobación o acción'],[('Credenciales inválidas','Verifique correo y contraseña; consulte si la cuenta está activa.'),('Acceso restringido','Solicite al administrador el permiso del módulo y acción.'),('No se pudo completar la operación','Confirme el mensaje; soporte debe revisar la API y MariaDB.'),('Referencia ya existente','Busque el pago registrado antes de usar otra referencia.'),('Pago superior al saldo','Revise el saldo del crédito y del convenio.'),('Sin filas en el listado','Quite filtros y compruebe los permisos y datos registrados.'),('No llega el mensaje de alerta','La entrega externa aún no está integrada; verifique la bandeja de acciones.')])
    heading(d,'10 Glosario');table(d,['Término','Significado'],[('Cartera en mora','Créditos con obligaciones pendientes fuera de la fecha acordada.'),('Gestión','Actividad registrada para dar seguimiento al cobro.'),('Convenio','Acuerdo de pago con cuotas y frecuencia.'),('Referencia','Identificador único del abono registrado.'),('Puntaje','Indicador orientativo calculado por reglas; no es probabilidad calibrada.'),('Bandeja pendiente','Registro de acción preparada sin confirmación de entrega externa.')])
    heading(d,'Anexo A Práctica guiada');para(d,'En un ambiente de pruebas, registre un cliente ficticio, cree un convenio y registre un abono con una referencia de prueba. Verifique cuotas, saldo e historial. No utilice datos reales para prácticas ni duplique referencias.')
    return d

def technical_manual():
    d=newdoc('Manual técnico','Instalación administración y mantenimiento')
    heading(d,'1 Introducción');heading(d,'1.1 Objetivo y alcance',2);para(d,'Este documento guía al responsable técnico en la instalación, configuración, mantenimiento, verificación y diagnóstico de la aplicación JME. Describe la implementación observada en el proyecto y sus límites funcionales.')
    heading(d,'1.2 Perfil del responsable',2);para(d,'Se requiere experiencia básica con Windows o un servidor compatible, terminal, Node.js, pnpm, SQL, MariaDB, DBeaver, redes locales y administración de credenciales. Las tareas financieras y restauraciones deben coordinarse con el responsable de los datos.')
    heading(d,'2 Descripción y arquitectura');heading(d,'2.1 Recorrido de una solicitud',2);para(d,'El navegador ejecuta React, que consulta endpoints bajo /api. Express procesa JSON, autentica el token y verifica el permiso; el módulo correspondiente valida la entrada y consulta MariaDB mediante mysql2. Una operación de pago abre una transacción, bloquea filas, actualiza los registros relacionados y confirma o revierte el conjunto.')
    heading(d,'2.2 Organización del proyecto',2);table(d,['Ubicación','Responsabilidad'],[('src/pages','Pantallas y formularios React.'),('src/context','Sesión, permisos visibles y datos de la API.'),('src/services/api.ts','Cliente HTTP y tratamiento de respuestas.'),('server/app.ts','Configuración Express y montaje de rutas.'),('server/modules','Módulos de autenticación, usuarios, clientes, créditos, convenios, pagos, gestiones, reportes y alertas.'),('server/shared','Conexión, transacciones, seguridad y errores HTTP.'),('server/database','Migración y carga inicial.'),('database','Creación de base y esquema SQL.'),('server/tests','Pruebas de dominio, HTTP e integración.')])
    heading(d,'2.3 Reglas que debe conservar la API',2);bullets(d,['Una cuenta de crédito consolidada por cliente; el NIT y las referencias de pago son únicos.','El abono no puede superar el saldo del crédito ni el del convenio seleccionado.','Pagos, saldo, cuotas, convenio y auditoría se modifican en una sola transacción.','El autor de una gestión se obtiene de la sesión; el navegador no decide la identidad.','Las alertas usan reglas de mora y no acreditan pagos ni envían mensajes por sí mismas.'])
    heading(d,'3 Requisitos e instalación local');heading(d,'3.1 Preparación del entorno',2);bullets(d,['Node.js 22.14 o superior y pnpm instalado.','MariaDB en ejecución y DBeaver con conexión al servidor. El entorno local observado usa MariaDB 10.4 de XAMPP; el proyecto incluye una opción Docker con MariaDB 11.4.','Conectividad al puerto de MariaDB y disponibilidad de puerto para Node.js.','Cuenta administradora en MariaDB para crear base, tablas y permisos.'])
    heading(d,'3.2 Crear base y tablas en DBeaver',2);steps(d,['Inicie MariaDB y pruebe la conexión desde DBeaver a 127.0.0.1 y el puerto configurado, habitualmente 3306.','Ejecute database/000-create-database.sql completo; seleccione la base jme.','Ejecute database/001-schema.sql como script completo (Alt+X).','Ejecute SHOW TABLES y confirme las 11 tablas indicadas en la sección de datos.','Cree una cuenta de aplicación local y concédale SELECT, INSERT, UPDATE y DELETE sobre jme.*.'])
    para(d,'El archivo docs/mariadb-dbeaver.md contiene el ejemplo de creación de usuario. Si se utiliza pnpm db:migrate en lugar de DBeaver, la cuenta que ejecute la migración necesita permisos DDL. La migración inicial usa CREATE TABLE IF NOT EXISTS y no actualiza columnas de tablas existentes.')
    heading(d,'3.3 Variables y secretos',2);table(d,['Variable','Propósito'],[('PORT','Puerto HTTP; 3000 por defecto.'),('DB_HOST / DB_PORT','Dirección y puerto de MariaDB.'),('DB_NAME','Base de datos, habitualmente jme.'),('DB_USER / DB_PASSWORD','Cuenta y contraseña de la aplicación.'),('SEED_ADMIN_PASSWORD','Clave inicial para pnpm db:seed; mínimo 12 caracteres.'),('PREDICTION_INTERVAL_MINUTES','Intervalo del lote en minutos; 0 lo desactiva.'),('DB_ROOT_PASSWORD','Solo para la inicialización de Docker.')])
    para(d,'Copie .env.example a .env solo si no existe. No sobrescriba configuraciones existentes ni publique el archivo. Variables ya definidas en el entorno pueden prevalecer sobre dotenv. Reinicie Node.js después de modificarlas.')
    heading(d,'3.4 Desarrollo y puesta en marcha',2);steps(d,['Desde la raíz ejecute pnpm install.','Con la base creada configure las variables de entorno.','Si necesita la cuenta inicial, configure SEED_ADMIN_PASSWORD y ejecute pnpm db:seed.','Inicie con pnpm dev y abra la URL indicada en consola.','Compruebe GET /api/health, el inicio de sesión y la lectura de clientes.'])
    para(d,'El comando de carga usa INSERT IGNORE y no reemplaza la contraseña de un administrador existente. pnpm db:seed --demo carga datos ficticios opcionales. El puerto puede cambiarse con PORT. Un 500 de salud requiere revisar la conexión MariaDB.')
    heading(d,'3.5 Docker y ejecución de producción',2);para(d,'docker compose configura una instancia MariaDB 11.4 opcional con volumen jme_mariadb. Configure DB_PASSWORD y DB_ROOT_PASSWORD antes de iniciarla; no reutilice un volumen MySQL sin una migración validada. Para producción, pnpm build compila la interfaz y pnpm start inicia Express. El arranque actual requiere tsx disponible; el proxy debe terminar HTTPS y aplicar la configuración del entorno.')
    heading(d,'4 Base de datos');heading(d,'4.1 Tablas y relaciones',2);table(d,['Tabla','Función y relación'],[('users','Cuentas, rol, estado, hash de contraseña y perfil JSON.'),('sessions','Hash de token, usuario y expiración.'),('clients','Identidad y expediente; código y NIT únicos.'),('credits','Cuenta de crédito única por cliente; saldo y capital en centavos.'),('agreements','Convenios asociados a clientes.'),('installments','Cuotas y abonos por convenio y número de cuota.'),('payments','Abonos con referencia única y autor.'),('activities','Gestiones con cliente y gestor.'),('alerts','Alertas por cliente y regla única.'),('notification_outbox','Acciones pendientes de entrega por alerta.'),('audit_log','Autor, acción, entidad y fecha.')])
    heading(d,'4.2 Integridad financiera',2);para(d,'Los montos financieros normalizados usan BIGINT en centavos. El pago usa bloqueo FOR UPDATE sobre cliente y crédito, valida saldo y referencia, aplica cuotas ordenadas, actualiza datos de presentación y registra auditoría. Cualquier excepción revierte la transacción. Las fechas mensuales de cuotas se ajustan al último día válido del mes; el residuo se aplica a la última cuota.')
    heading(d,'4.3 JSON y mantenimiento del esquema',2);para(d,'Las columnas payload conservan campos de presentación y permisos. En MariaDB JSON es un alias de texto con validación; no edite payload directamente sin mantener coherencia con columnas financieras. Los cambios futuros requieren una migración versionada y prueba sobre una copia antes de aplicarse.')
    heading(d,'5 Servicios HTTP');heading(d,'5.1 Autenticación y autorización',2);para(d,'POST /api/auth/login valida correo y contraseña. El servidor genera un token aleatorio; solo su hash se almacena en sessions y el navegador guarda el token en sessionStorage. La sesión vence a las ocho horas. El middleware consulta estado y permisos actuales; el rol Administrador tiene acceso completo. El cierre de sesión revoca el token.')
    heading(d,'5.2 Catálogo de rutas',2);table(d,['Método y ruta','Responsabilidad'],[('GET /api/health','Verifica conectividad con la base.'),('POST /api/auth/login; GET /api/auth/me; POST /api/auth/logout','Inicio, consulta y cierre de sesión.'),('GET/POST /api/clients; PATCH /api/clients/:id','Consulta, registro y actualización de expedientes.'),('GET /api/credits; GET /api/credits/:id/statement','Créditos y estado de cuenta.'),('GET/POST /api/agreements','Consulta y creación de convenios.'),('GET/POST /api/payments','Consulta y registro de pagos.'),('GET/POST /api/activities','Consulta y registro de gestiones.'),('GET/POST /api/users; PATCH permisos/estado','Administración de cuentas.'),('GET /api/reports','Resumen de cartera y pagos.'),('GET /api/alerts; POST run, resolve, queue','Consulta, evaluación y gestión de alertas.')])
    heading(d,'5.3 Códigos y validaciones',2);para(d,'La API devuelve 400 por validación o sobrepago, 401 por sesión inválida, 403 por permiso insuficiente, 404 si la entidad no existe y 409 por conflicto o duplicado. Los errores contienen message. Para probar utilice una base de pruebas y nunca incluya tokens o contraseñas en capturas o incidencias.')
    heading(d,'6 Alertas y automatización');para(d,'El lote usa score = min(98, redondeo(días × 0.65 + ajuste por saldo)); el ajuste es 15 si el saldo supera Q25,000 y 5 en otro caso. Genera alertas para saldo positivo y al menos 30 días de mora, con una clave por cliente y fecha. El puntaje es orientativo, no un modelo estadístico entrenado; el canal y la ventana son reglas generales. notification_outbox conserva una acción pendiente y no existe proveedor de mensajería conectado.')
    heading(d,'7 Administración y seguridad');bullets(d,['Contraseñas con scrypt y salt aleatorio; no guardar claves en texto plano.','El límite de 10 intentos fallidos por IP se almacena en memoria durante 15 minutos; debe evaluarse su comportamiento detrás de proxy.','La desactivación revoca sesiones; no permite que el administrador desactive su propia cuenta.','Separar usuarios de base para operación y migraciones; limitar acceso de red y usar HTTPS.','No incorporar .env, tokens ni respaldos con datos reales a control de versiones.'])
    heading(d,'8 Mantenimiento recuperación y despliegue');heading(d,'8.1 Respaldo y restauración',2);steps(d,['Identifique la base, destino y responsable de la ventana de respaldo.','Genere un respaldo lógico con las herramientas autorizadas de MariaDB o DBeaver y guárdelo cifrado con control de acceso.','Registre fecha, versión y ubicación del respaldo sin guardar contraseñas en el registro.','Restaure primero en una base aislada; compare tablas, conteos y operaciones representativas.','Para recuperación real siga el procedimiento aprobado y confirme integridad antes de reabrir el servicio.'])
    heading(d,'8.2 Control de cambios',2);para(d,'Antes de una entrega conserve una copia del código y respaldo consistente de base. Ejecute migraciones probadas, construya la aplicación y confirme salud, autenticación, consulta y flujos financieros en un entorno de pruebas. Para regresar a una versión anterior verifique compatibilidad del esquema; una reversión del código no revierte automáticamente los datos.')
    heading(d,'9 Pruebas y validación');para(d,'Ejecute pnpm lint, pnpm test y pnpm build. La prueba de integración se habilita mediante RUN_DB_TESTS=1 sobre una base exclusiva migrada y con administrador inicial; verifica cliente, convenio, pago, duplicado, sobrepago y persistencia. No la ejecute sobre una base de producción. Documente la versión, fecha, responsable y resultado.')
    heading(d,'10 Diagnóstico de incidencias');table(d,['Síntoma','Diagnóstico y acción'],[('ECONNREFUSED 127.0.0.1:3306','Compruebe que MariaDB esté iniciado y escuche en el host y puerto.'),('ER_ACCESS_DENIED_ERROR','Compruebe .env, contraseña efectiva y privilegios de la cuenta; reinicie Node.'),('EADDRINUSE','Identifique el proceso que usa PORT o configure otro puerto.'),('Credenciales inválidas','Compruebe cuenta activa y contraseña; seed no cambia claves existentes.'),('403 o acceso restringido','Compruebe rol y permisos de acción del usuario.'),('409 registro existente','Revise NIT, correo o referencia duplicada según operación.'),('Datos no aparecen','Compruebe filtros, permisos, /api/bootstrap y estado de la base.'),('Acción de alerta sin entrega','La bandeja no tiene proveedor de entrega integrado.')])
    heading(d,'11 Pantallas de referencia');image(d,'dashboard','Panel del sistema','El panel permite comprobar que la aplicación presenta sus indicadores y accesos tras la autenticación.');image(d,'usuarios','Administración de usuarios','Los usuarios y sus permisos se administran desde la interfaz con una cuenta autorizada.')
    heading(d,'12 Glosario técnico');table(d,['Término','Definición'],[('API','Servicios HTTP usados por el navegador.'),('Monolito modular','Una aplicación desplegada como un proceso con responsabilidades separadas.'),('Transacción','Conjunto de operaciones confirmadas o revertidas conjuntamente.'),('Hash','Resultado no reversible utilizado para verificar contraseñas o tokens.'),('Migración','Cambio controlado en la estructura de base de datos.'),('Outbox','Tabla de acciones pendientes de entrega externa.')])
    heading(d,'Anexo A Comprobación de entrega');steps(d,['Comprobar la disponibilidad del servidor y la conexión MariaDB.','Verificar la configuración sin compartir secretos.','Ejecutar análisis de tipos, pruebas y compilación.','Probar ingreso y permisos en una cuenta de prueba.','Revisar respaldo y restauración en ambiente aislado.'])
    return d

